import { OrderRepository } from './repository';
import { ListRequest, Page } from './types';

function invalid(): never {
  throw new Error('invalid request');
}

function parseCursor(cursor: string): { createdAt: string; id: string } {
  const parts = cursor.split('|');
  if (parts.length !== 2 || parts[0] === '' || parts[1] === '') invalid();
  return { createdAt: parts[0], id: parts[1] };
}

export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}

  list(request: ListRequest): Page {
    if (!request.tenant || !Number.isInteger(request.limit) || request.limit < 1 || request.limit > 100) {
      invalid();
    }
    const after = request.cursor === undefined || request.cursor === null
      ? undefined
      : parseCursor(request.cursor);
    const { items, hasMore } = this.repository.listPage({
      tenant: request.tenant,
      limit: request.limit,
      after,
    });
    const last = items[items.length - 1];
    const nextCursor = hasMore && last ? `${last.createdAt}|${last.id}` : null;
    return { items, nextCursor };
  }
}

